export const STATUSES=['未拍','已拍待检查','确认可用','需要补拍'];
export const CATEGORIES=['车辆','场地','设备','道具'];
export const uid=()=>crypto.randomUUID().toLowerCase();
export const now=()=>new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const readable=t=>new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
export const clone=x=>structuredClone(x);
export const blank=x=>!x.trim();
export function validDay(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;}
export function templates(){const c=(topic,picture,caution='')=>({id:uid(),topic,picture,caution,required:true}); return [
{id:uid(),name:'静态讲车',cards:[c('本期问题与车型介绍','人物开场与车辆全景','现场确认年款与配置'),c('外观讲解','车身及相关细节'),c('座舱讲解','讲解内容对应的车内细节'),c('空间与使用方式','实际演示与补充细节','只记录真实观察'),c('围绕核心问题收尾','人物总结')]},
{id:uid(),name:'单项功能体验',cards:[c('要验证什么','人物提出问题与功能入口'),c('操作条件与步骤','功能操作过程','确认安全条件，不预设结果'),c('实际体验','老板体验与对应画面','保留真实感受'),c('观察与限制','补充条件与细节'),c('回答本期问题','人物收尾')]},
{id:uid(),name:'试驾记录',cards:[c('路线与本期问题','出发前人物介绍','确认车辆与场地许可'),c('起步与低速体验','安全拍摄的车内及补充画面','驾驶者专心驾驶，禁止危险操作'),c('实际路段体验','对应路段与口述观察','记录路况与条件，不预设评价'),c('停车后复盘','人物复述真实感受'),c('补充细节与总结','遗漏细节及人物收尾')]}];}
export function shot(card={}){return {id:uid(),number:'',topic:'',picture:'',caution:'',required:true,pointIDs:[],status:'未拍',cancelled:false,cancellationReason:'',experience:'',retakeReason:'',materialName:'',materialLocation:'',preferredTake:'',publicNote:'',internalNote:'',needsRecheck:false,...card,id:uid()};}
export function appendShots(p,cards){let next=Math.max(p.nextShotNumber,1,...p.shots.map(s=>Number(s.number.slice(1))+1));for(const card of cards){p.shots.push(shot({...card,number:'S'+String(next++).padStart(3,'0')}));}p.nextShotNumber=next;}
export function newProject(name='新拍摄项目'){const p={id:uid(),name,shootDate:today(),createdAt:now(),updatedAt:now(),isDemo:false,vehicle:{model:'',preparedYear:'',preparedTrim:'',actualYear:'',actualTrim:'',needsConfirmation:false},coreQuestion:'',points:[],parameters:[],checklist:[],shots:[],nextShotNumber:1,draftScript:'',scriptVersions:[],handoffs:[],needsDateConfirmation:false};
 const items=[['确认现场车辆年款与配置','确认车辆及钥匙可用'],['确认场地和拍摄许可','检查环境与安全条件'],['相机、电池与存储卡','收音设备与监听检查'],['本期需要的道具与物品']]; CATEGORIES.forEach((category,i)=>items[i].forEach(text=>p.checklist.push({id:uid(),category,text,done:false,notApplicable:false})));return p;}
export function confirmScript(p){if(blank(p.draftScript))throw Error('口播稿为空，请先填写。');p.scriptVersions.push({id:uid(),number:(p.scriptVersions.at(-1)?.number||0)+1,confirmedAt:now(),text:p.draftScript});}
export function demo(){const p=newProject('【虚构示例】星河 S1 拍摄练习');p.isDemo=true;p.vehicle={model:'星河 S1（虚构车型）',preparedYear:'2026（虚构）',preparedTrim:'演示配置 A（虚构）',actualYear:'2026（虚构）',actualTrim:'演示配置 B（虚构）',needsConfirmation:false};p.coreQuestion='【虚构练习】如何围绕一个问题完成准备、拍摄与交接？';p.points=[{id:uid(),text:'确认现场车辆与准备资料是否一致'},{id:uid(),text:'记录真实观察，不预设体验结论'}];p.draftScript='【虚构示例，不用于真实发布】本期围绕一个测试问题，记录现场观察；车型、配置和下方参数均为虚构测试数据。';confirmScript(p);appendShots(p,templates()[0].cards);p.shots[0].pointIDs=[p.points[0].id];Object.assign(p.shots[1],{status:'已拍待检查',materialName:'DEMO_S002_take02.mov',materialLocation:'虚构素材目录/外观',preferredTake:'第 2 条（演示）'});Object.assign(p.shots[2],{status:'确认可用',experience:'【虚构记录】仅供流程测试，不代表老板真实评价。',internalNote:'内部测试备注：默认不进入交接单。'});Object.assign(p.shots[3],{status:'需要补拍',retakeReason:'【演示】细节画面需补拍。'});Object.assign(p.shots[4],{cancelled:true,cancellationReason:'【演示】时间不足，收尾待补。'});p.parameters=[{id:uid(),name:'车长（虚构测试参数）',value:'9999 mm（虚构）',source:'虚构测试说明，非车辆资料',sourceDate:today(),verification:'待核实',needsRecheck:false}];return p;}
function vehicleRevision(next,prev){return ['model','preparedYear','preparedTrim','actualYear','actualTrim'].some(k=>{const before=String(prev?.[k]??'');return !blank(before)&&before!==String(next?.[k]??'');});}
export function audit(p,old){const vehicle=vehicleRevision(p.vehicle,old.vehicle);const script=p.draftScript!==old.draftScript||p.coreQuestion!==old.coreQuestion;const changed=new Set([...p.points,...old.points].filter(pt=>p.points.find(x=>x.id===pt.id)?.text!==old.points.find(x=>x.id===pt.id)?.text).map(x=>x.id));if(vehicle){p.vehicle.needsConfirmation=true;p.parameters.forEach(x=>x.needsRecheck=true);}for(const s of p.shots){const o=old.shots.find(x=>x.id===s.id);if(vehicle||script||[...s.pointIDs,...(o?.pointIDs||[])].some(id=>changed.has(id))||(o&&['topic','picture','caution','pointIDs'].some(k=>JSON.stringify(s[k])!==JSON.stringify(o[k]))))s.needsRecheck=true;}p.updatedAt=now();}
export function copyProject(source,name){const p=clone(source);Object.assign(p,{id:uid(),name,shootDate:'',createdAt:now(),updatedAt:now(),needsDateConfirmation:true,scriptVersions:[],handoffs:[]});p.vehicle.needsConfirmation=true;p.parameters.forEach(x=>Object.assign(x,{verification:'待核实',needsRecheck:true}));p.checklist.forEach(x=>Object.assign(x,{done:false,notApplicable:false}));p.shots.forEach(x=>Object.assign(x,{status:'未拍',cancelled:false,cancellationReason:'',experience:'',retakeReason:'',materialName:'',materialLocation:'',preferredTake:'',publicNote:'',internalNote:'',needsRecheck:true}));return p;}
export const verified=p=>p.verification==='已核实'&&!p.needsRecheck&&[p.name,p.value,p.source].every(x=>!blank(x))&&validDay(p.sourceDate);
export const usable=s=>!s.cancelled&&s.status==='确认可用'&&!s.needsRecheck;
export const counts=p=>({all:p.shots.length,usable:p.shots.filter(usable).length,required:p.shots.filter(s=>s.required).length,requiredUsable:p.shots.filter(s=>s.required&&usable(s)).length});
export function issues(p){const r=[];const add=(text,target='base',shotID=null)=>r.push({text,target,shotID});if(!validDay(p.shootDate)||p.needsDateConfirmation)add('拍摄日期尚未填写或重新确认。');if(blank(p.vehicle.model))add('车型尚未填写。');if(['preparedYear','preparedTrim','actualYear','actualTrim'].some(k=>blank(p.vehicle[k])))add('准备资料或现场车辆的年款、配置待补充核实。','vehicle');if(blank(p.coreQuestion))add('本期核心问题尚未填写。');if(!p.shots.length)add('尚未建立镜头清单。','structure');if(p.vehicle.needsConfirmation)add('车型、年款或配置需要重新确认。','vehicle');if(!p.scriptVersions.length)add('尚无确认稿。','script');else if(p.scriptVersions.at(-1).text!==p.draftScript)add('编辑稿已修改，尚未确认为新版本；交接沿用最近确认稿。','script');for(const s of p.shots){const shotIssue=t=>add(t,'shot',s.id);if(s.cancelled){if(s.required)shotIssue(`取消的必拍镜头 ${s.number} · ${s.topic}：${s.cancellationReason}`);continue;}const unshot=s.status==='未拍';if(s.required&&unshot)shotIssue(s.needsRecheck?`必拍未拍 ${s.number} · ${s.topic}（关联内容变更，拍摄前请重查）`:`必拍未拍 ${s.number} · ${s.topic}`);if(s.status==='已拍待检查')shotIssue(`已拍待检查 ${s.number} · ${s.topic}`);if(s.status==='需要补拍')shotIssue(`需要补拍 ${s.number} · ${s.topic}：${s.retakeReason||'补拍原因未填写'}`);if(s.needsRecheck&&!(unshot&&s.required))shotIssue(`关联内容变更，需重查镜头 ${s.number} · ${s.topic}`);if(s.status==='确认可用'&&(blank(s.materialName)||blank(s.materialLocation)))shotIssue(`可用镜头 ${s.number} 的素材文件名或位置尚未登记。`);}for(const v of p.parameters)if(!verified(v))add(`待核实资料：${v.name||'未命名参数'} · ${v.value||'数值未填写'}`,'vehicle');return r;}
export const defaultOptions=()=>({experiences:true,publicNotes:true,internalNotes:false});
const mdInline=(value,empty)=>{const text=String(value??'').replace(/\s+/g,' ').trim();return text||empty;};
const mdCell=(value,empty='—')=>mdInline(value,empty).replace(/\|/g,'\\|');
const mdBlock=value=>{const text=String(value??'').replace(/\r\n/g,'\n').trim();return text||'无';};
export function handoffMarkdown(p,options=defaultOptions(),at=now(),number=(p.handoffs.at(-1)?.number||0)+1,list=issues(p)){const v=p.scriptVersions.at(-1);const lines=['# 小怡拍摄助手 · 拍摄交接单',''];if(p.isDemo)lines.push('> 【虚构示例，仅用于流程测试，不代表真实车型、参数或体验】','');lines.push(`- **项目**：${mdInline(p.name,'未填写')}`,`- **拍摄日期**：${p.shootDate||'未填写'}`,`- **车型**：${mdInline(p.vehicle.model,'未填写')}`,`- **主题 / 核心问题**：${mdInline(p.coreQuestion,'未填写')}`,`- **准备资料**：${mdInline(p.vehicle.preparedYear,'未填写')} · ${mdInline(p.vehicle.preparedTrim,'未填写')}`,`- **现场车辆**：${mdInline(p.vehicle.actualYear,'未填写')} · ${mdInline(p.vehicle.actualTrim,'未填写')}`,`- **交接版本**：V${number}`,`- **导出时间**：${readable(at)}（中国标准时间）`,`- **交接状态**：${list.length?'带待办交接':'已完成检查'}`,'','## 素材速查','','| 镜头 | 讲什么 | 状态 | 素材文件名 | 素材位置 | 优选条次 |','| --- | --- | --- | --- | --- | --- |');if(!p.shots.length)lines.push('| — | 尚未建立镜头清单 | — | — | — | — |');for(const s of p.shots){const state=s.cancelled?'已取消':s.status;lines.push(`| ${mdCell(s.number)} · ${s.required?'必拍':'选拍'} | ${mdCell(s.topic,'未填写')} | ${mdCell(state)} | ${mdCell(s.materialName,'未登记')} | ${mdCell(s.materialLocation,'未登记')} | ${mdCell(s.preferredTake,'未选择')} |`);}lines.push('','## 一、最近确认稿','');if(v)lines.push(`**确认稿 V${v.number}** · ${readable(v.confirmedAt)}`,'',mdBlock(v.text));else lines.push('尚无确认稿；不将编辑稿冒充确认稿。');lines.push('','## 二、镜头与素材对应关系（按现场顺序）','');if(!p.shots.length)lines.push('尚未建立镜头清单。','');for(const s of p.shots){const state=s.cancelled?'已取消':s.status;lines.push(`### ${s.number} · ${s.required?'必拍':'选拍'} · ${state}`,'',`- **素材文件名**：${mdInline(s.materialName,'未登记')}`,`- **素材位置**：${mdInline(s.materialLocation,'未登记')}`,`- **优选条次**：${mdInline(s.preferredTake,'未选择')}`,'',`**讲什么**`,'',mdBlock(s.topic),'',`**拍什么**`,'',mdBlock(s.picture),'',`**注意事项**`,'',mdBlock(s.caution));if(s.needsRecheck&&!s.cancelled)lines.push('','**复核提醒**','','关联内容已变更，需人工重查，当前不计入可用数。');const linked=p.points.filter(x=>s.pointIDs.includes(x.id));if(linked.length)lines.push('','**关联讲解重点**','',linked.map(x=>mdInline(x.text,'未填写重点')).join('；'));if(s.cancelled)lines.push('','**取消原因**','',mdBlock(s.cancellationReason));if(options.experiences&&s.experience)lines.push('','**体验记录**','',mdBlock(s.experience));if(s.retakeReason)lines.push('','**补拍原因**','',mdBlock(s.retakeReason));if(options.publicNotes&&s.publicNote)lines.push('','**公开备注**','',mdBlock(s.publicNote));if(options.internalNotes&&s.internalNote)lines.push('','**内部备注**','',mdBlock(s.internalNote));lines.push('');}lines.push('## 三、车辆资料与核实状态','');if(!p.parameters.length)lines.push('未登记参数；不推断车型资料。','');for(const x of p.parameters)lines.push(`- **${mdInline(x.name,'未命名参数')}**：${mdInline(x.value,'数值未填写')} · ${verified(x)?'已核实':'待核实'}`,`  - 来源：${mdInline(x.source,'未登记')} · 来源日期：${x.sourceDate||'未登记'}`);lines.push('','## 四、未解决问题','');if(list.length)list.forEach(x=>lines.push('- '+mdInline(x.text,'')));else lines.push('无已登记的未解决问题。参数真实性与素材可用性仍由人工确认。');lines.push('','---','','说明：本交接单为文字记录，不包含原始视频。');return lines.join('\n');}
export function handoff(p,options=defaultOptions(),at=now()){const number=(p.handoffs.at(-1)?.number||0)+1;const list=issues(p);const v=p.scriptVersions.at(-1);const lines=['小怡拍摄助手 · 拍摄交接单',...(p.isDemo?['【虚构示例，仅用于流程测试，不代表真实车型、参数或体验】']:[]),`项目：${p.name}`,`拍摄日期：${p.shootDate||'未填写'}`,`车型：${p.vehicle.model||'未填写'}`,`主题 / 核心问题：${p.coreQuestion||'未填写'}`,`准备资料：${p.vehicle.preparedYear} · ${p.vehicle.preparedTrim}`,`现场车辆：${p.vehicle.actualYear} · ${p.vehicle.actualTrim}`,`交接版本：V${number}`,`导出时间：${readable(at)}（中国标准时间）`,`交接状态：${list.length?'带待办交接':'已完成检查'}`,'','一、最近确认稿',v?`确认稿 V${v.number} · ${readable(v.confirmedAt)}\n${v.text}`:'尚无确认稿；不将编辑稿冒充确认稿。','','二、镜头与素材对应关系（按现场顺序）'];for(const s of p.shots){lines.push(`${s.number} · ${s.required?'必拍':'选拍'} · ${s.cancelled?'已取消':s.status}`,`讲什么：${s.topic}`,`拍什么：${s.picture}`,`注意事项：${s.caution}`);if(s.needsRecheck&&!s.cancelled)lines.push('复核提醒：关联内容已变更，需人工重查，当前不计入可用数。');const linked=p.points.filter(x=>s.pointIDs.includes(x.id));if(linked.length)lines.push('关联讲解重点：'+linked.map(x=>x.text).join('；'));if(s.cancelled)lines.push('取消原因：'+s.cancellationReason);lines.push('素材文件名：'+(s.materialName||'未登记'),'素材位置：'+(s.materialLocation||'未登记'),'优选条次：'+(s.preferredTake||'未选择'));if(options.experiences&&s.experience)lines.push('体验记录：'+s.experience);if(s.retakeReason)lines.push('补拍原因：'+s.retakeReason);if(options.publicNotes&&s.publicNote)lines.push('公开备注：'+s.publicNote);if(options.internalNotes&&s.internalNote)lines.push('内部备注：'+s.internalNote);lines.push('');}lines.push('三、车辆资料与核实状态');if(!p.parameters.length)lines.push('未登记参数；不推断车型资料。');p.parameters.forEach(x=>lines.push(`${x.name}：${x.value} · ${verified(x)?'已核实':'待核实'}\n来源：${x.source||'未登记'} · 来源日期：${x.sourceDate||'未登记'}`));lines.push('','四、未解决问题',...(list.length?list.map(x=>'• '+x.text):['无已登记的未解决问题。参数真实性与素材可用性仍由人工确认。']),'','说明：本交接单为文字记录，不包含原始视频。');return {id:uid(),number,exportedAt:at,text:lines.join('\n'),markdown:handoffMarkdown(p,options,at,number,list),options:clone(options)};}
const fail=m=>{throw Error(m);};const str=(o,k)=>{if(typeof o[k]!=='string')fail('文件字段不合法：'+k);};const bool=(o,k)=>{if(typeof o[k]!=='boolean')fail('文件字段不合法：'+k);};const arr=(o,k,limit=2000)=>{if(!Array.isArray(o[k])||o[k].length>limit)fail('记录数组不合法或过大：'+k);};const uniq=(a,label)=>{if(a.some(x=>typeof x!=='string'||!x)||new Set(a).size!==a.length)fail(label+'编号为空或重复。');};
const time=s=>typeof s==='string'&&!isNaN(Date.parse(s));
export function validateProject(p){if(!p||typeof p!=='object')fail('无效的项目');['id','name','shootDate','createdAt','updatedAt','coreQuestion','draftScript'].forEach(k=>str(p,k));if(blank(p.name)||p.name.length>150||!p.id||!time(p.createdAt)||!time(p.updatedAt)||p.draftScript.length>500000)fail('项目名称、稿件长度或时间不合法。');['isDemo','needsDateConfirmation'].forEach(k=>bool(p,k));if(!p.vehicle||typeof p.vehicle!=='object')fail('缺少车辆资料');['model','preparedYear','preparedTrim','actualYear','actualTrim'].forEach(k=>str(p.vehicle,k));bool(p.vehicle,'needsConfirmation');for(const k of ['points','parameters','checklist','shots','scriptVersions','handoffs']){arr(p,k);uniq(p[k].map(x=>x?.id),k);}p.points.forEach(x=>str(x,'text'));p.parameters.forEach(x=>{['name','value','source','sourceDate','verification'].forEach(k=>str(x,k));bool(x,'needsRecheck');if(!['已核实','待核实'].includes(x.verification))fail('资料状态不合法');});p.checklist.forEach(x=>{str(x,'text');if(!CATEGORIES.includes(x.category))fail('检查分类不合法');bool(x,'done');bool(x,'notApplicable');});uniq(p.shots.map(x=>x.number),'镜头');p.shots.forEach(s=>{['number','topic','picture','caution','status','cancellationReason','experience','retakeReason','materialName','materialLocation','preferredTake','publicNote','internalNote'].forEach(k=>str(s,k));['required','cancelled','needsRecheck'].forEach(k=>bool(s,k));arr(s,'pointIDs');if(!/^S\d{3,}$/.test(s.number)||!STATUSES.includes(s.status)||s.cancelled&&blank(s.cancellationReason)||s.pointIDs.some(id=>!p.points.some(x=>x.id===id)))fail('镜头编号、状态、取消原因或重点关联不合法');});if(!Number.isSafeInteger(p.nextShotNumber)||p.nextShotNumber<=Math.max(0,...p.shots.map(s=>Number(s.number.slice(1)))))fail('镜头编号计数不合法');for(const k of ['scriptVersions','handoffs']){let n=0;for(const v of p[k]){if(!Number.isSafeInteger(v.number)||v.number<=n)fail('历史版本编号不合法');n=v.number;str(v,'text');if(!time(k==='scriptVersions'?v.confirmedAt:v.exportedAt))fail('历史时间不合法');if(k==='handoffs'){if(!v.options)fail('缺少导出选项');['experiences','publicNotes','internalNotes'].forEach(key=>bool(v.options,key));}}}return p;}
export const backup=p=>{const project=clone(p),normalize=t=>new Date(t).toISOString().replace(/\.\d{3}Z$/, 'Z');project.createdAt=normalize(project.createdAt);project.updatedAt=normalize(project.updatedAt);project.scriptVersions.forEach(v=>v.confirmedAt=normalize(v.confirmedAt));project.handoffs.forEach(v=>v.exportedAt=normalize(v.exportedAt));return {format:'xiaoyi-shoot-project-backup',schemaVersion:1,exportedAt:now(),includesOriginalVideo:false,project};};
export function decodeBackup(text){if(new TextEncoder().encode(text).length>10*1024*1024)fail('备份超过 10 MB。');const b=JSON.parse(text);if(b.format!=='xiaoyi-shoot-project-backup'||b.schemaVersion!==1||b.includesOriginalVideo!==false||!time(b.exportedAt))fail('这不是支持的项目备份文件。');validateProject(b.project);return b;}
export function validateLibrary(l){if(!l||l.format!=='xiaoyi-shoot-library'||l.schemaVersion!==1)fail('不支持的本机记录格式');arr(l,'projects',1000);arr(l,'templates',3);if(l.templates.length!==3)fail('模板数量不正确');uniq(l.projects.map(p=>p.id),'项目');uniq(l.templates.map(t=>t.id),'模板');l.projects.forEach(validateProject);l.templates.forEach(t=>{str(t,'name');arr(t,'cards');uniq(t.cards.map(c=>c.id),'结构镜头');t.cards.forEach(c=>{['topic','picture','caution'].forEach(k=>str(c,k));bool(c,'required');});});if(new TextEncoder().encode(JSON.stringify(l)).length>10*1024*1024)fail('记录超过 10 MB，请先导出备份。');return l;}
export class BrowserRepository{
 async open(){this.db=await new Promise((resolve,reject)=>{const r=indexedDB.open('xiaoyi-shoot-assistant',1);r.onupgradeneeded=()=>r.result.createObjectStore('records');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('请关闭旧标签页后重试。'));});}
 async read(key){return new Promise((resolve,reject)=>{const tx=this.db.transaction('records','readonly'),r=tx.objectStore('records').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 async write(library,revision){validateLibrary(library);return new Promise((resolve,reject)=>{const tx=this.db.transaction('records','readwrite'),s=tx.objectStore('records'),r=s.get('primary');let reason='';r.onsuccess=()=>{const current=r.result;if((current?.revision||0)!==revision){reason='另一个标签页已修改项目。请先导出当前项目备份，再刷新此页，避免覆盖。';tx.abort();return;}if(current){try{validateLibrary(current.library);s.put(current,'previous');}catch{}}s.put({revision:revision+1,library},'primary');};tx.oncomplete=()=>resolve(revision+1);tx.onerror=()=>reject(Error(reason||tx.error?.message||'浏览器存储写入失败'));tx.onabort=()=>reject(Error(reason||'浏览器存储写入失败'));});}
}
export class Store{
 constructor(repo,changed=()=>{}){this.repo=repo;this.changed=changed;this.library={format:'xiaoyi-shoot-library',schemaVersion:1,projects:[],templates:templates()};this.revision=0;this.generation=0;this.savedGeneration=0;this.state='正在读取';this.error='';this.blocked=false;this.undo=[];}
 async init(){try{await this.repo.open();const current=await this.repo.read('primary');if(current){this.revision=current.revision;this.library=validateLibrary(current.library);this.state='已保存';}else {if(await this.repo.read('previous'))throw Error('主记录缺失，请恢复上一份有效数据。');this.library.projects=[demo()];this.touch();await this.flush();}}catch(e){this.blocked=true;this.state='读取失败';this.error=e.message;}this.changed();}
 project(id){return this.library.projects.find(p=>p.id===id);}
 touch(){if(this.blocked)return;this.generation++;this.state='正在保存';clearTimeout(this.timer);this.timer=setTimeout(()=>this.flush(),220);this.changed();}
 modify(id,edit,audited=true){if(this.blocked)throw Error('请先恢复本机数据。');const p=this.project(id);if(!p)return;const old=clone(p);edit(p);if(JSON.stringify(p)===JSON.stringify(old))return;if(audited)audit(p,old);else p.updatedAt=now();this.touch();}
 async flush(){clearTimeout(this.timer);if(this.blocked)return false;if(this.saving){await this.saving;if(this.savedGeneration<this.generation&&!this.error)return this.flush();return !this.error;}if(this.savedGeneration===this.generation){this.state='已保存';return true;}const generation=this.generation,snapshot=clone(this.library);this.saving=(async()=>{try{this.revision=await this.repo.write(snapshot,this.revision);this.savedGeneration=generation;this.error='';this.state=generation===this.generation?'已保存':'正在保存';return true;}catch(e){this.error=e.message;this.state='保存失败';return false;}finally{this.saving=null;this.changed();}})();const ok=await this.saving;if(ok&&this.savedGeneration<this.generation)return this.flush();return ok;}
 unique(name){let s=name,n=2;while(this.library.projects.some(p=>p.name.trim().toLowerCase()===s.trim().toLowerCase()))s=`${name}（${n++}）`;return s;}
 add(p){if(this.blocked)throw Error('请先恢复本机数据。');p.name=this.unique(p.name);this.library.projects.unshift(p);this.touch();return p.id;}
 status(pid,sid,status,reason=null){const s=this.project(pid)?.shots.find(s=>s.id===sid);if(!s)return;if(reason!==null&&blank(reason))throw Error('请填写取消原因。');if(reason===null&&s.status===status&&!s.cancelled&&!(status==='确认可用'&&s.needsRecheck))return;this.undo.push({pid,sid,status:s.status,cancelled:s.cancelled,cancellationReason:s.cancellationReason,needsRecheck:s.needsRecheck});if(this.undo.length>100)this.undo.shift();this.modify(pid,p=>{const x=p.shots.find(x=>x.id===sid);if(reason!==null){x.cancelled=true;x.cancellationReason=reason;}else {x.status=status;x.cancelled=false;x.cancellationReason='';if(status==='确认可用')x.needsRecheck=false;}},false);}
 undoStatus(pid){const i=this.undo.findLastIndex(x=>x.pid===pid);if(i<0)return;const u=this.undo.splice(i,1)[0];this.modify(pid,p=>{const x=p.shots.find(x=>x.id===u.sid);if(x)Object.assign(x,{status:u.status,cancelled:u.cancelled,cancellationReason:u.cancellationReason,needsRecheck:x.needsRecheck||u.needsRecheck});},false);}
 async recover(){const record=await this.repo.read('previous');if(!record)throw Error('没有可恢复的上一份有效数据。');this.library=clone(validateLibrary(record.library));const current=await this.repo.read('primary');this.revision=current?.revision||0;this.blocked=false;this.undo=[];this.touch();return this.flush();}
}
